var text = String(input.csv || "");
var lines = text.split(/\r?\n/).filter(function (l) { return l.trim() !== ""; });
function splitRow(line) {
  var out = []; var cur = ""; var inQ = false;
  for (var i = 0; i < line.length; i++) {
    var ch = line[i];
    if (inQ) {
      if (ch === "\"") { if (line[i + 1] === "\"") { cur += "\""; i++; } else { inQ = false; } }
      else { cur += ch; }
    } else if (ch === "\"") { inQ = true; }
    else if (ch === ",") { out.push(cur); cur = ""; }
    else { cur += ch; }
  }
  out.push(cur);
  return out;
}
var rows = lines.map(splitRow);
return { headers: rows[0] || [], rows: rows.slice(1), count: Math.max(0, rows.length - 1) };
